import argparse


def validate_esc(esc):
    """Validate esc options\n
    Give an error if the characters aren't '*?[]'
    """
    esc = esc.replace("]", "[")
    argset = set(esc)
    charset = {"*", "?", "["}
    if argset.difference(charset):
        err = "input character is not '*?[]'"
        raise argparse.ArgumentTypeError(err)

    return "".join(argset)

