def neighborhood(index, npoints, maxdist=1):
    """
    Returns the neighbourhood of the current index,
    = all points of the grid separated by up to
    *maxdist* from current point.

    @type index: int
    @type npoints: int
    @type maxdist int
    @rtype: list of int
    """
