def median(list_in):
    """
    Calculates the median of the data

    :param list_in: A list
    :return: float
    """
    list_in.sort()
    half = int(len(list_in) / 2)
    if len(list_in) % 2 != 0:
        return float(list_in[half])
    elif len(list_in) % 2 ==0:
        value = (list_in[half - 1] + list_in[half]) / 2
        return float(value)

