from typing import Dict


def most_repeated_character(string: str) -> str:
    """
    Find the most repeated character in a string.
    :param string:
    :return:
    """
    map: Dict[str, int] = {}

    for letter in string:
        if letter not in map:
            map[letter] = 1
        else:
            map[letter] += 1

    return sorted(map.items(), key=lambda item: item[1], reverse=True)[0][0]

def _is_arg_name(s, index, node):
    """Search for the name of the argument. Right-to-left."""
    if not node.arg:
        return False
    return s[index : index+len(node.arg)] == node.arg

